
(function(){
if(!location.pathname.includes('/tools/events/register_cdo/eventid/23975'))return;
var body,scheduled=false,writing=false,lastSuggested=-1,mode='suggested';
var rates={'9829':24,'9830':15,'10680':80,'10677':0};
var names={'9829':'Adults (12+)','9830':'Children (ages 3–11)','10680':'Adult group (up to 4)','10677':'Children under 3'};
function money(n){return '$'+Number(n).toFixed(2);}
function text(el,value){if(el&&el.textContent!==value)el.textContent=value;}
function suggested(){var total=0,family=0;document.querySelectorAll('#performance_32450_reservations .reservation').forEach(function(row){var category=row.querySelector('.g100, .float_right > .inline_block:not(.price-display)');var name=category?category.textContent:'';if((name.includes('Family')||name.includes('Adult group')))family++;else if(name.includes('Adults'))total+=24;else if(name.includes('Children')&&!name.includes('under'))total+=15;});if(family)total+=80+Math.max(0,family-4)*20;return total;}
function writeAmount(input,value){var str=Number(value).toFixed(2);if(input.value===str)return;writing=true;input.value=str;input.dispatchEvent(new Event('input',{bubbles:true}));writing=false;}
function initChoice(){var input=document.getElementById('TotalDonation'),summary=document.getElementById('Summary');if(!input||!summary)return null;
var card=document.getElementById('tcContributionChoice');if(!card){var oldrow=input.closest('.large_top_margin.medium_bottom_margin');if(oldrow)oldrow.classList.add('tc-native-donation-row');
card=document.createElement('div');card.id='tcContributionChoice';card.innerHTML='<p>Your contribution helps cover dinner and welcome everyone to the table.</p><label class="tc-contribution-option"><input type="radio" name="tc_contribution_choice" id="tcContributeSuggested" value="suggested" checked><span><strong id="tcSuggestedAmountLabel"></strong><small>Based on the guests joining you.</small></span></label><label class="tc-contribution-option"><input type="radio" name="tc_contribution_choice" id="tcContributeHelping" value="helping"><span><strong id="tcHelpingAmountLabel"></strong><small>Includes $36 to help welcome another family.</small></span></label><label class="tc-contribution-option"><input type="radio" name="tc_contribution_choice" id="tcContributeCustom" value="custom"><span><strong>Choose your own amount</strong><small>Give more or less—whatever works for your family.</small></span></label><div id="tcCustomContributionWrap" hidden><label for="tcCustomAmount">Your contribution amount (CAD)</label><div class="tc-amount-input"><span aria-hidden="true">$</span><input id="tcCustomAmount" type="number" min="0" step="0.01" inputmode="decimal" aria-label="Your contribution amount" class="co_form_input"></div><div id="tcContributionError" hidden>Please enter an amount of $0 or more.</div></div><p id="tcContributionReassurance">Everyone is welcome—no explanation needed. You can enter $0.</p>';
var heading=summary.querySelector('.title.large');if(heading)heading.insertAdjacentElement('afterend',card);else summary.prepend(card);
var custom=card.querySelector('#tcCustomAmount');custom.value=input.value;
card.querySelectorAll('input[type=radio]').forEach(function(r){r.addEventListener('change',function(){mode=r.value;sync();if(mode==='custom'){custom.value=input.value;custom.setCustomValidity('');card.querySelector('#tcContributionError').hidden=true;custom.focus();}});});
custom.addEventListener('input',function(){var valid=custom.value!==''&&Number.isFinite(Number(custom.value))&&Number(custom.value)>=0;custom.setCustomValidity(valid?'':'Please enter an amount of $0 or more.');card.querySelector('#tcContributionError').hidden=valid;if(valid)writeAmount(input,Number(custom.value));});body.addEventListener('click',function(event){if(event.target.closest('#SubmitButton')&&mode==='custom'&&!custom.checkValidity()){event.preventDefault();event.stopImmediatePropagation();custom.reportValidity();}},true);
var extra=document.getElementById('AdditionalInformation');if(extra){var details=document.createElement('details');details.id='tcMoreSponsorship';var toggle=document.createElement('summary');toggle.textContent='Help make this evening and future events possible';details.appendChild(toggle);card.appendChild(details);details.appendChild(extra);if(extra.querySelector('input[type=checkbox]:checked'))details.open=true;var description=extra.querySelector('.form-html');if(description)description.textContent='Help cover the challah, wine and dinner, and make future community gatherings possible. Any amount selected below is added to your contribution.';}
}
return input;}
function sync(){scheduled=false;var input=initChoice();if(!input)return;var amount=suggested();text(document.getElementById('tcSuggestedAmountLabel'),'Suggested contribution — '+money(amount));document.getElementById('tcCustomContributionWrap').hidden=mode!=='custom';text(document.getElementById('tcHelpingAmountLabel'),'Help another family join — '+money(amount+36)+' total');if(mode==='suggested'||mode==='helping'){input.setCustomValidity('');document.getElementById('tcContributionError').hidden=true;writeAmount(input,amount+(mode==='helping'?36:0));}else if(lastSuggested===-1&&input.value===''){writeAmount(input,amount);}lastSuggested=amount;
var select=document.getElementById('performance_32450_priceCategory');if(select)Array.from(select.options).forEach(function(option){if(names[option.value])text(option,names[option.value]+' — '+(option.value==='10677'?'Free':money(rates[option.value])+' suggested'));});
var help=document.querySelector('#Performances > .regular');text(help,'Choose who’s coming.');if(select)select.setAttribute('aria-label','Guest type');var label=select&&select.parentNode.querySelector('div');text(label,'Guest type');
var intro=document.getElementById('tcShabbatNightIntroV5');if(intro){var details=intro.querySelectorAll('.tc-detail');if(details[2]){text(details[2].querySelector('.tc-detail-label'),'Suggested contribution');var info=details[2].querySelector('.tc-detail-main');if(info&&info.innerHTML!=='Adults (12+): $24<br>Children (3–11): $15<br>Under 3: Free')info.innerHTML='Adults (12+): $24<br>Children (3–11): $15<br>Under 3: Free';}text(intro.querySelector('.tc-help-note'),'Adult group: $80 for up to four adults, then $20 per additional adult. Choose whatever works for you. Everyone is welcome.');}
document.querySelectorAll('#Totals > .clearfix').forEach(function(row){var label=row.querySelector('.float_left');if(!label)return;var content=label.textContent.trim();if(content.indexOf('Subtotal for Cozy Fall Shabbat')===0){row.style.setProperty('display','none','important');}else if(content.indexOf('Subtotal for Additional Information')===0)text(label,'Optional sponsorship:');else if(content.indexOf('Donation:')===0)text(label,'Your contribution:');else if(content.indexOf('Total:')===0)text(label,'Total contribution:');});var button=document.querySelector('#SubmitButton span');text(button,'Reserve my seats');
}
function schedule(){if(!scheduled){scheduled=true;setTimeout(sync,80);}}
function start(){body=document.getElementById('RegisterBody');if(!body)return;sync();new MutationObserver(schedule).observe(body,{childList:true,subtree:true});body.addEventListener('change',schedule);body.addEventListener('click',schedule);setTimeout(sync,400);setTimeout(sync,1200);}
if(document.readyState==='complete')start();else window.addEventListener('load',start);
})();
